// src/components/Certificate/PublicCertificateVerification.jsx
import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { CertificateService } from '../../models/services/certificateService';
import './PublicCertificateVerification.css';

const PublicCertificateVerification = () => {
  const { certificateId } = useParams();
  const [verificationResult, setVerificationResult] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const verifyCertificate = async () => {
      if (certificateId) {
        try {
          const result = await CertificateService.verifyCertificate(certificateId);
          setVerificationResult(result);
        } catch (error) {
          setVerificationResult({
            isValid: false,
            message: 'Erreur lors de la vérification'
          });
        } finally {
          setLoading(false);
        }
      }
    };

    verifyCertificate();
  }, [certificateId]);

  if (loading) {
    return (
      <div className="verification-container">
        <div className="verification-loading">
          <div className="spinner"></div>
          <p>Vérification du certificat en cours...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="verification-container">
      <div className="verification-card">
        <div className={`verification-header ${verificationResult.isValid ? 'valid' : 'invalid'}`}>
          <h1>
            {verificationResult.isValid ? '✅ Certificat Valide' : '❌ Certificat Invalide'}
          </h1>
        </div>
        
        <div className="verification-body">
          <p className="verification-message">{verificationResult.message}</p>
          
          {verificationResult.isValid && verificationResult.certificate && (
            <div className="certificate-details">
              <h3>Détails du Certificat</h3>
              <div className="details-grid">
                <div className="detail-item">
                  <label>Étudiant:</label>
                  <span>{verificationResult.certificate.studentName}</span>
                </div>
                <div className="detail-item">
                  <label>Cours:</label>
                  <span>{verificationResult.certificate.courseTitle}</span>
                </div>
                <div className="detail-item">
                  <label>Score:</label>
                  <span>{verificationResult.certificate.finalScore}%</span>
                </div>
                <div className="detail-item">
                  <label>Date d'émission:</label>
                  <span>
                    {new Date(verificationResult.certificate.issueDate).toLocaleDateString('fr-FR')}
                  </span>
                </div>
                <div className="detail-item">
                  <label>ID Certificat:</label>
                  <span className="certificate-id">{verificationResult.certificate.certificateId}</span>
                </div>
              </div>
            </div>
          )}
        </div>
        
        <div className="verification-footer">
          <p>
            <small>
              Vérifié le {new Date().toLocaleDateString('fr-FR')} via EduPlatform
            </small>
          </p>
        </div>
      </div>
    </div>
  );
};

export default PublicCertificateVerification;
